// Native SAM target acquisition regression. Uses isolated save fixtures only.
#define Generate_Mission_Starts Chain_Regression
#include "../tests/samblast_engine.cpp"
#undef Generate_Mission_Starts
static BuildingClass* Ready(const std::string& dir){Reset(dir);auto s=new BuildingClass(STRUCT_SAM,HOUSE_GOOD);Check("place infantry targeting SAM",Put(s,Center()));++ScenarioInit;s->Begin_Mode(BSTATE_IDLE);--ScenarioInit;s->Assign_Mission(MISSION_GUARD);s->Commence();return s;}
static void Types(const std::string& dir){
 for(int type=INFANTRY_FIRST;type<INFANTRY_COUNT;++type){auto s=Ready(dir);auto a=new InfantryClass((InfantryType)type,HOUSE_BAD);if(!Put(a,XY_Cell(Cell_X(Coord_Cell(s->Coord))+5,Cell_Y(Coord_Cell(s->Coord)))))continue;a->IsDiscoveredByPlayer=true;a->Strength=30000;int score=0;bool valid=s->Evaluate_Object(THREAT_NORMAL,1<<RTTI_INFANTRY,0,a,score);auto found=s->Greatest_Threat(THREAT_NORMAL);std::printf("TYPE %d legal=%d score=%d found=%u expected=%u range=%d\n",type,int(valid),score,unsigned(found),unsigned(a->As_Target()),int(s->In_Range(a,0)));if(valid)Check("all otherwise valid infantry types auto-acquire",found==a->As_Target());}
}
static void SharedCell(const std::string& dir,int exclusion){
 auto s=Ready(dir);CELL cell=XY_Cell(Cell_X(Coord_Cell(s->Coord))+5,Cell_Y(Coord_Cell(s->Coord)));std::vector<InfantryClass*> group;
 for(int i=0;i<5;++i){auto a=new InfantryClass(INFANTRY_E1,HOUSE_BAD);Check("place five infantry in one real cell",a->Unlimbo(Cell_Coord(cell),DIR_N));a->IsDiscoveredByPlayer=true;a->Strength=30000;group.push_back(a);}
 auto head=static_cast<InfantryClass*>(Map[cell].Cell_Occupier());Check("occupier is one of the real infantry group",std::find(group.begin(),group.end(),head)!=group.end());if(exclusion==0)head->IsDiscoveredByPlayer=false;else if(exclusion==1)head->Cloak=CLOAKED;else if(exclusion==2)head->Strength=0;
 auto found=s->Greatest_Threat(THREAT_NORMAL);int eligible=0;for(auto a:group){int value=0;if(s->Evaluate_Object(THREAT_NORMAL,1<<RTTI_INFANTRY,0,a,value)&&a->Strength>0)++eligible;}
 std::printf("SHARED reason=%d head=%u found=%u eligible=%d\n",exclusion,unsigned(head->As_Target()),unsigned(found),eligible);Check("one excluded infantry never hides other visible infantry in the same cell",found!=TARGET_NONE&&found!=head->As_Target());
 s->Assign_Target(TARGET_NONE);s->Mission_Guard();Check("guard automatically acquires shared-cell visible infantry",s->TarCom!=TARGET_NONE&&s->TarCom!=head->As_Target());s->Commence();bool fired=false;for(int tick=0;tick<500&&!fired;++tick){++Frame;s->AI();fired=Bullets.Count()>0;}Check("native SAM AI fires without manual targeting at shared-cell infantry",fired);
}
static void Moving(const std::string& dir){auto s=Ready(dir);auto a=new InfantryClass(INFANTRY_E1,HOUSE_BAD);Check("place moving enemy infantry",Put(a,XY_Cell(Cell_X(Coord_Cell(s->Coord))+5,Cell_Y(Coord_Cell(s->Coord)))));a->Strength=30000;a->IsDiscoveredByPlayer=true;bool fired=false;for(int tick=0;tick<500&&!fired;++tick){a->Coord=Coord_Move(a->Coord,tick%100<50?DIR_N:DIR_S,8);++Frame;s->AI();fired=Bullets.Count()>0;}Check("moving infantry can be auto-acquired and fired upon",fired);}
static void StaleTarget(const std::string& dir,bool limbo){
 auto s=Ready(dir);auto c=Coord_Cell(s->Coord);auto old=new InfantryClass(INFANTRY_E1,HOUSE_BAD);auto live=new InfantryClass(INFANTRY_E1,HOUSE_BAD);Check("place stale target fixture",Put(old,XY_Cell(Cell_X(c)+5,Cell_Y(c)))&&Put(live,XY_Cell(Cell_X(c)+6,Cell_Y(c))));old->IsDiscoveredByPlayer=live->IsDiscoveredByPlayer=true;old->Strength=live->Strength=30000;auto oldID=old->As_Target();if(limbo)old->Limbo();else old->Strength=0;s->Assign_Target(oldID);s->Assign_Mission(MISSION_ATTACK);s->Commence();Check("SAM rejects dead or limbo target despite active object ID",!Campaign_SAM_Target_Allowed(s,oldID));bool fired=false;for(int tick=0;tick<500&&!fired;++tick){++Frame;s->AI();fired=Bullets.Count()>0;}Check("stale target is dropped and live infantry is attacked",fired&&s->TarCom==live->As_Target());
}
static void NoEligibleTargets(const std::string& dir){auto s=Ready(dir);auto c=Coord_Cell(s->Coord);for(int i=0;i<5;++i){auto a=new InfantryClass(INFANTRY_E1,HOUSE_BAD);Put(a,XY_Cell(Cell_X(c)+5,Cell_Y(c)));a->IsDiscoveredByPlayer=false;}Check("SAM does not reveal or attack entirely hidden infantry",s->Greatest_Threat(THREAT_NORMAL)==TARGET_NONE);}
bool Generate_Mission_Starts(const char* directory){std::string dir(directory);Types(dir);for(int reason:{0,1,2})SharedCell(dir,reason);Moving(dir);StaleTarget(dir,false);StaleTarget(dir,true);NoEligibleTargets(dir);std::printf("TOTAL FAILURES %d\n",failures);return failures==0;}
